import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.B0LNVsFV.js";const r="/contract-mgmt-docs/assets/09-document-upload.CLSyMnEk.png",m=JSON.parse('{"title":"9. Document upload","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/09-document-upload.md","filePath":"chapters/09-document-upload.md"}'),i={name:"chapters/09-document-upload.md"};function d(s,e,l,h,c,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="_9-document-upload" tabindex="-1">9. Document upload <a class="header-anchor" href="#_9-document-upload" aria-label="Permalink to &quot;9. Document upload&quot;">​</a></h1><h2 id="read" tabindex="-1">Read <a class="header-anchor" href="#read" aria-label="Permalink to &quot;Read&quot;">​</a></h2><ul><li><a href="https://rxjs.dev/guide/overview" target="_blank" rel="noreferrer">RxJS overview</a></li><li><a href="https://rxjs.dev/api/index/function/forkJoin" target="_blank" rel="noreferrer">forkJoin</a></li><li><a href="https://rxjs.dev/api/operators/concatMap" target="_blank" rel="noreferrer">concatMap</a></li><li><a href="https://rxjs.dev/api/operators/switchMap" target="_blank" rel="noreferrer">switchMap</a></li><li><a href="https://rxjs.dev/api/operators/catchError" target="_blank" rel="noreferrer">catchError</a></li></ul><h2 id="practice" tabindex="-1">Practice <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;Practice&quot;">​</a></h2><p>Implement on the Offer step:</p><table tabindex="0"><thead><tr><th>What</th><th>Business description</th></tr></thead><tbody><tr><td>Service calls</td><td>Upload a document to a contract and download a document. The BFF accepts one file per upload request</td></tr><tr><td>File selection directive</td><td>A reusable directive for a file input that reports the chosen file and clears the input</td></tr><tr><td>Choosing files</td><td>A file picker that accepts only pdf and docx. A chosen file is <strong>not</strong> sent to the BFF; it is kept in browser memory in a signal. Documents can only be added while the contract is in Offer</td></tr><tr><td>Documents table</td><td>Shows both files in memory and documents already stored in the BFF in one table. Each row has the document name, a status (<code>Pending</code> for files in memory or <code>Uploaded</code> for stored documents), a download icon and a delete icon. The download icon is enabled only for uploaded documents; deleting a pending document removes it from memory. Files in memory are lost when the page is reloaded</td></tr><tr><td>Continue button</td><td>Disabled until the stored documents plus the files in memory are at least 2. Pressing it runs the flow below and moves the contract to Review</td></tr><tr><td>Visibility</td><td>The file picker and the continue button only exist while the contract is in Offer; the documents table stays visible afterwards. The pending-document delete action only exists while the contract is in Offer</td></tr><tr><td>Translations</td><td>All new texts in English and German</td></tr></tbody></table><p>The flow, managed with RxJS:</p><table tabindex="0"><thead><tr><th>Step</th><th>Business description</th></tr></thead><tbody><tr><td>1</td><td>Send one upload request for every file in memory</td></tr><tr><td>2</td><td>Wait until <strong>all</strong> uploads have finished. Combine them into one stream that completes only when every upload is done (see <code>forkJoin</code>, or <code>concatMap</code> to send them one after another)</td></tr><tr><td>3</td><td>Only then call the transition endpoint with the target stage Review. Chain it after the uploads (see <code>switchMap</code>) so it never starts earlier</td></tr><tr><td>4</td><td>When everything succeeds, clear the files from memory and show the contract returned by the transition. Its status is Review, so the stepper moves to the review step. The final signing is the next chapter</td></tr><tr><td>Failure</td><td>If an upload fails, do not call the transition. Show the BFF message (see <code>catchError</code>). Files that were already uploaded are removed from memory so a retry does not upload them twice; the failed ones stay</td></tr><tr><td>While running</td><td>Disable the continue button and the file picker so the flow cannot be started twice</td></tr><tr><td>Nothing to upload</td><td>When all documents are already stored and nothing is in memory, the button only calls the transition</td></tr></tbody></table><p>Choose two files, remove one and add another, then continue. Watch the network tab: one upload request per file, and the transition request starts only after the last upload has finished.</p><h2 id="visual-mockup" tabindex="-1">Visual mockup <a class="header-anchor" href="#visual-mockup" aria-label="Permalink to &quot;Visual mockup&quot;">​</a></h2><p><img src="'+r+'" alt="Offer-step document selection, pending files, stored files, and continue action"></p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><ul><li>The service uploads a file as a multipart form</li><li>The directive reports the chosen file</li><li>A chosen file is kept in memory and no request is sent</li><li>A pending file can be deleted from the documents table</li><li>An uploaded document can be downloaded using its download icon</li><li>Continue is disabled with one document in total, enabled with two</li><li>Continuing sends one upload request per file and sends the Review transition only after all uploads have been answered</li><li>If an upload fails, no transition request is sent and the message is shown</li><li>After a successful flow the memory list is empty</li></ul><p>Done when files wait in memory until the continue button uploads them all and moves the contract to Review, and the tests are green.</p><h2 id="what-to-explain" tabindex="-1">What to explain <a class="header-anchor" href="#what-to-explain" aria-label="Permalink to &quot;What to explain&quot;">​</a></h2><ul><li>RxJs operator orchestration</li></ul>',16)])])}const f=t(i,[["render",d]]);export{m as __pageData,f as default};
